def _trivial_tmpl(pointed_ketiv, unpointed_ketiv, pointed_qere):
    return wtp.mktmpl(
        [
            ['מ:קו"כ-אם-2'],
            [pointed_ketiv],
            [unpointed_ketiv],
            [pointed_qere],
        ],
        ignore_equals=True,
    )


def _std_kq_tmpl(pointed_ketiv, pointed_qere):
    return wtp.mktmpl([['כו"ק'], [pointed_ketiv], [pointed_qere]], ignore_equals=True)


class TrivialKqSubtypeClassifierTests(unittest.TestCase):
    def test_classify_xolam_he(self):
        tmpl = _trivial_tmpl("סוּתֹֽה", "סותה", "סוּתֽוֹ")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.XOLAM_HE)

    def test_classify_qyv(self):
        tmpl = _trivial_tmpl("עֹֽלוֹתָ֔ו", "עלותו", "עֹֽלוֹתָ֔יו")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.QYV)

    def test_classify_hi_spelled_hu(self):
        tmpl = _trivial_tmpl("הַהִ֖וא", "ההוא", "הַהִ֖יא")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.HI_SPELLED_HU)

    def test_classify_n3rh_spelled_n3r(self):
        tmpl = _trivial_tmpl("הַֽנַּעֲרָ֖", "הנער", "הַֽנַּעֲרָ֖ה")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.N3RH_SPELLED_N3R)

    def test_classify_extra_alef_with_rafeh(self):
        tmpl = _trivial_tmpl("וַיֹּר֨אֿוּ", "ויראו", "וַיֹּר֨וּ")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.EXTRA_ALEF)

    def test_classify_extra_alef_plain(self):
        tmpl = _trivial_tmpl("מָרִ֕אי", "מראי", "מָרִ֕י")

        self.assertEqual(ktt.classify_tmpl(tmpl), ktt.EXTRA_ALEF)

    def test_leave_unmatched_blank(self):
        tmpl = _trivial_tmpl("סוּתֹֽה", "סותה", "סוּתִֽי")

        self.assertIsNone(ktt.classify_tmpl(tmpl))

    def test_subtype_for_path_uses_misc_for_unmatched(self):
        tmpl = _trivial_tmpl("סוּתֹֽה", "סותה", "סוּתִֽי")

        self.assertEqual(ktt.subtype_for_path(tmpl), ktt.MISC)


